<script setup lang="ts">import {ref,onMounted} from 'vue';import {useRoute,RouterLink} from 'vue-router';import {type Product,price,money,imageUrl,purchaseUrl,getEcommerceProduct} from '../lib/catalog';const route=useRoute();const item=ref<Product|null>(null),error=ref('');onMounted(async()=>{try{const slug=String(route.params.slug);item.value=await getEcommerceProduct(slug);if(!item.value)error.value='Produto não encontrado ou indisponível.';}catch(e){error.value=String(e)}})</script><template><div class="container detail"><RouterLink to="/" class="back">← Voltar ao catálogo</RouterLink><p v-if="error" class="notice error">{{error}}</p><div v-if="item" class="detail-grid"><img v-if="item.imagem_url" :src="imageUrl(item.imagem_url)" :alt="item.nome"/><div><div class="eyebrow">SHOPPING DE FLORES</div><h1>{{item.nome}}</h1><p>{{item.descricao}}</p><h2>{{money(price(item))}}</h2><del v-if="price(item)<item.preco">{{money(item.preco)}}</del><a class="btn primary full" :href="purchaseUrl(item)">Comprar agora ↗</a><p class="checkout-note">Você concluirá a compra no Shopping de Flores, com escolha da entrega e pagamento seguro.</p></div></div><div v-else-if="!error" class="notice">Carregando produto...</div></div></template>